const { handleMessage, getBusiness } = require("../lib/lia.js");

const PAGE = "<!doctype html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"color-scheme\" content=\"dark\">\n<title>Prenota – Barbiere Mario</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#050608; --bg2:#0A0D12; --card:#0E131B; --card2:#161D29; --line:#1C2532; --line2:#2A3648;\n  --ink:#F9F6F0; --muted:#9BA6B5;\n  --accent:#2DD2DC; --accent2:#0AA2EE; --on-accent:#031016; --accent-soft:#0B2C33; --accent-ink:#A5EDF2;\n  --green:#3FE08A; --err:#FF8A8A;\n  color-scheme:dark;\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:env(safe-area-inset-bottom,0px);\n}\n:root{--logo:url(\"data:image/png;base64,\");}\nhtml{background:var(--bg);}\n*{box-sizing:border-box;}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"SF Pro Text\",\"Inter\",\"Helvetica Neue\",Helvetica,Arial,sans-serif;font-size:16px;line-height:1.45;-webkit-font-smoothing:antialiased;}\nh1,h2,h3,p,ul{margin:0;}\nul{padding:0;list-style:none;}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:10px;}\n.logo{display:block;width:42px;height:42px;flex:none;background:url('?asset=lia-a') center / contain no-repeat;}\n\n.app{max-width:640px;margin:0 auto;height:100vh;height:100dvh;display:flex;flex-direction:column;overflow:hidden;}\n.top{padding:16px 20px 0;}\n.top-row{display:flex;align-items:center;gap:12px;}\n.top h1{font-size:1.02rem;font-weight:700;letter-spacing:-0.01em;}\n.top small{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:.82rem;margin-top:2px;}\n.onlineDot{width:8px;height:8px;border-radius:50%;background:var(--green);flex:none;animation:onlinePulse 2s ease-in-out infinite;}\n@keyframes onlinePulse{0%,100%{box-shadow:0 0 0 0 rgba(63,224,138,.55);}70%{box-shadow:0 0 0 6px rgba(63,224,138,0);}}\n@media (prefers-reduced-motion: reduce){.onlineDot{animation:none;}}\n\n.seg{margin:16px 0 0;display:flex;padding:4px;border-radius:16px;background:var(--card);border:1px solid var(--line);}\n.seg button{flex:1;min-height:44px;border:0;border-radius:12px;background:transparent;color:var(--muted);font-family:inherit;font-size:.96rem;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;}\n.seg button[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);}\n.seg button svg{flex:none;}\n\n.panel{flex:1;display:flex;flex-direction:column;min-height:0;}\n.panel[hidden]{display:none;}\n\n/* ---------- chat ---------- */\n#chatMsgs{flex:1;padding:18px 20px 8px;display:flex;flex-direction:column;gap:10px;overflow-y:auto;}\n.row{display:flex;}\n.row.me{justify-content:flex-end;}\n.row.lia{justify-content:flex-start;}\n.b{max-width:82%;padding:11px 16px;border-radius:20px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:1rem;opacity:0;transform:translateY(10px) scale(.98);animation:pop .38s cubic-bezier(.2,.9,.3,1.2) forwards;}\n.row.me .b{background:linear-gradient(160deg,var(--accent) 0%,var(--accent2) 100%);color:var(--on-accent);font-weight:500;border-bottom-right-radius:6px;}\n .row.lia .b{background:var(--card);border:1px solid var(--line);border-bottom-left-radius:6px;}\n.cal-add{display:inline-flex;align-items:center;justify-content:center;margin-top:9px;padding:10px 14px;border-radius:999px;background:var(--accent);color:var(--on-accent);font-size:.9rem;font-weight:700;text-decoration:none;}\n@keyframes pop{to{opacity:1;transform:none;}}\n@media (prefers-reduced-motion: reduce){.b{opacity:1;transform:none;animation:none;}}\n.typing{display:inline-flex;align-items:center;gap:4px;padding:14px 18px;border-radius:20px;border-bottom-left-radius:6px;background:var(--card);border:1px solid var(--line);}\n.typing i{width:7px;height:7px;border-radius:50%;background:var(--muted);animation:bounce 1.1s ease-in-out infinite;}\n.typing i:nth-child(2){animation-delay:.15s;} .typing i:nth-child(3){animation-delay:.3s;}\n@keyframes bounce{0%,60%,100%{transform:translateY(0);opacity:.5;}30%{transform:translateY(-5px);opacity:1;}}\n@media (prefers-reduced-motion: reduce){.typing i{animation:none;opacity:.85;}}\n.quick{display:flex;flex-wrap:wrap;gap:8px;padding:2px 0 6px;}\n.qbtn{min-height:38px;padding:0 16px;border-radius:999px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);font-family:inherit;font-size:.92rem;font-weight:500;cursor:pointer;}\n.qbtn:hover{border-color:var(--accent);}\n.chatbar{position:sticky;bottom:0;display:flex;gap:8px;align-items:flex-end;padding:12px 16px calc(12px + env(safe-area-inset-bottom,0px));background:linear-gradient(to top, var(--bg) 60%, transparent);}\n.chatbar input{flex:1;min-height:48px;padding:0 18px;border-radius:24px;border:1px solid var(--line);background:var(--card);color:var(--ink);font-family:inherit;font-size:1rem;}\n.chatbar input:focus{outline:none;border-color:var(--accent);}\n.sendbtn{flex:none;width:48px;height:48px;border-radius:50%;border:none;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;cursor:pointer;}\n.sendbtn[disabled]{opacity:.4;}\n\n/* ---------- prenota da solo ---------- */\n.col{padding:20px 20px 110px;overflow-y:auto;flex:1;}\n.col h2{font-size:1.5rem;font-weight:700;letter-spacing:-0.03em;line-height:1.15;outline:none;}\n.col .lead{margin-top:8px;color:var(--muted);font-size:1rem;}\n\n.svc-list{margin-top:22px;display:grid;gap:10px;}\n.svc-opt{display:flex;align-items:center;gap:16px;width:100%;text-align:left;padding:16px 18px;border-radius:18px;border:1.5px solid var(--line2);background:var(--card);color:var(--ink);font-family:inherit;cursor:pointer;}\n.svc-opt[aria-pressed=\"true\"]{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);}\n.svc-opt .mid{flex:1;min-width:0;}\n.svc-opt b{display:block;font-size:1.04rem;font-weight:600;}\n.svc-opt span{display:block;color:var(--muted);font-size:.9rem;margin-top:2px;}\n.svc-opt .price{flex:none;font-size:1.05rem;font-weight:700;}\n\n.cal{margin-top:22px;padding:18px;border-radius:20px;background:var(--card);border:1px solid var(--line2);}\n.cal-head{display:flex;align-items:center;justify-content:space-between;}\n.cal-head b{font-size:1.05rem;font-weight:700;letter-spacing:-0.01em;text-transform:capitalize;}\n.cal-nav{display:flex;gap:6px;}\n.cal-nav button{width:36px;height:36px;border-radius:10px;border:1px solid var(--line2);background:var(--card2);color:var(--ink);display:grid;place-items:center;cursor:pointer;}\n.cal-nav button[disabled]{opacity:.3;cursor:default;}\n.cal-dow{margin-top:14px;display:grid;grid-template-columns:repeat(7,1fr);gap:4px;}\n.cal-dow span{text-align:center;font-size:.72rem;color:var(--muted);font-weight:600;text-transform:uppercase;}\n.cal-grid{margin-top:4px;display:grid;grid-template-columns:repeat(7,1fr);gap:4px;}\n.cal-day{position:relative;aspect-ratio:1;border-radius:12px;border:0;background:transparent;color:var(--ink);font-family:inherit;font-size:.95rem;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;}\n.cal-day.pad{visibility:hidden;}\n.cal-day.off{color:#3E4A5C;cursor:default;}\n.cal-day.today::after{content:\"\";position:absolute;bottom:5px;width:4px;height:4px;border-radius:50%;background:var(--accent);}\n.cal-day[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);}\n.cal-day[aria-pressed=\"true\"]::after{background:var(--on-accent);}\n.cal-day:disabled{color:#2A3242;cursor:default;}\n\n.time-group{margin-top:22px;}\n.time-group h3{font-size:.86rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;margin-bottom:10px;}\n.time-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(80px,1fr));gap:9px;}\n.time-opt{min-height:46px;border-radius:13px;border:1.5px solid var(--line2);background:var(--card);color:var(--ink);font-family:inherit;font-size:.96rem;font-weight:600;cursor:pointer;}\n.time-opt[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent);}\n.time-empty{margin-top:18px;padding:26px 18px;text-align:center;color:var(--muted);border:1px dashed var(--line2);border-radius:16px;font-size:.94rem;}\n\n/* passaggio calendario -> orari, sovrapposto con uno scorrimento */\n.cal-stage{position:relative;overflow:hidden;transition:height .32s cubic-bezier(.2,.8,.2,1);}\n.cal-page,.time-page{position:absolute;left:0;right:0;top:0;transition:transform .32s cubic-bezier(.2,.8,.2,1), opacity .28s ease;}\n.cal-page{transform:translateX(0);opacity:1;}\n.time-page{transform:translateX(100%);opacity:0;pointer-events:none;}\n.cal-stage.show-time .cal-page{transform:translateX(-100%);opacity:0;pointer-events:none;}\n.cal-stage.show-time .time-page{transform:translateX(0);opacity:1;pointer-events:auto;}\n@media (prefers-reduced-motion: reduce){\n  .cal-stage,.cal-page,.time-page{transition:none;}\n}\n.time-back{display:inline-flex;align-items:center;gap:6px;background:transparent;border:0;color:var(--accent-ink);font-family:inherit;font-size:.92rem;font-weight:600;padding:2px 2px 4px;cursor:pointer;}\n.time-page .picked-date{margin-top:10px;font-size:1.02rem;font-weight:700;letter-spacing:-0.01em;text-transform:capitalize;}\n.time-page .time-inner{padding-top:2px;}\n\n.picked{margin-top:22px;padding:14px 16px;border-radius:16px;background:var(--card2);display:flex;align-items:center;gap:12px;}\n.picked .ic{flex:none;width:36px;height:36px;border-radius:10px;background:var(--accent-soft);color:var(--accent-ink);display:grid;place-items:center;}\n.picked b{display:block;font-size:.96rem;font-weight:600;}\n.picked span{display:block;color:var(--muted);font-size:.84rem;}\n\n.field{margin-top:16px;display:grid;gap:7px;}\n.field label{font-size:.88rem;font-weight:500;color:var(--muted);}\n.inp{width:100%;min-height:50px;padding:0 16px;border-radius:14px;border:1px solid var(--line2);background:var(--card);color:var(--ink);font-family:inherit;font-size:1rem;}\n.err-banner{margin-top:16px;padding:12px 14px;border-radius:14px;background:rgba(255,138,138,.08);border:1px solid var(--err);color:var(--err);font-size:.92rem;}\n.load{padding:60px 20px;text-align:center;color:var(--muted);}\n.err-page{margin:40px 20px;padding:20px;border-radius:16px;border:1px solid var(--err);color:var(--err);text-align:center;}\n.inp:focus{outline:none;border-color:var(--accent);}\n\n.actions{margin-top:26px;display:grid;gap:6px;}\n.btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 26px;border-radius:999px;font-family:inherit;font-size:1.02rem;font-weight:600;border:0;background:var(--accent);color:var(--on-accent);cursor:pointer;}\n.btn[disabled]{opacity:.4;cursor:default;}\n.btn.text{background:transparent;color:var(--muted);min-height:46px;font-weight:500;}\n\n.summary{margin-top:24px;padding:20px;border-radius:20px;background:var(--card);border:1px solid var(--line);display:grid;gap:12px;}\n.summary .r{display:flex;justify-content:space-between;font-size:.98rem;}\n.summary .r span:first-child{color:var(--muted);}\n.summary hr{border:none;border-top:1px solid var(--line);margin:0;}\n.done{display:flex;flex-direction:column;align-items:center;text-align:center;padding:22px 0 10px;}\n.done .check{width:68px;height:68px;border-radius:22px;background:linear-gradient(145deg,var(--accent),var(--accent2));color:var(--on-accent);display:grid;place-items:center;margin-bottom:22px;box-shadow:0 12px 34px rgba(45,210,220,.18);}\n.done h2{font-size:1.5rem;letter-spacing:-.025em;line-height:1.15;}\n.done>.lead{margin-top:10px;color:var(--muted);line-height:1.55;}\n.done .summary{width:100%;margin-top:28px;padding:22px;border-radius:24px;background:linear-gradient(145deg,var(--card2),var(--card));border:1px solid var(--line2);gap:0;box-shadow:0 18px 50px rgba(0,0,0,.18);}\n.done .summary .r{padding:13px 0;gap:24px;align-items:center;text-align:left;}\n.done .summary .r:first-child{padding-top:2px;}\n.done .summary .r:last-child{padding-bottom:2px;}\n.done .summary .r span:first-child{font-size:.86rem;}\n.done .summary .r b{text-align:right;font-size:.96rem;font-weight:600;line-height:1.35;}\n.done .summary hr{border-color:var(--line);}\n.done>.actions{width:100%;margin-top:18px;}\n.done>.actions+.actions{margin-top:8px;}\n.done>.actions .btn{width:100%;text-decoration:none;}\n.done>.actions .btn:not(.text){min-height:54px;box-shadow:0 10px 28px rgba(45,210,220,.12);}\n.done>.actions .btn.text{font-size:.94rem;}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"top\">\n    <div class=\"top-row\">\n      <span class=\"logo\" role=\"img\" aria-label=\"Lia\"></span>\n      <div><h1>Barbiere Mario</h1><small><span class=\"onlineDot\" aria-hidden=\"true\"></span>Online ora</small></div>\n    </div>\n    <div class=\"seg\" role=\"tablist\" aria-label=\"Come vuoi prenotare\">\n      <button type=\"button\" id=\"tabChat\" role=\"tab\" aria-pressed=\"true\">\n        <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 11.5a8.38 8.38 0 0 1-4.5 7.5 8.5 8.5 0 0 1-8.9-.4L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 8-8.5h.5a8.48 8.48 0 0 1 8 8v.5z\"></path></svg>\n        Chat con Lia\n      </button>\n      <button type=\"button\" id=\"tabBook\" role=\"tab\" aria-pressed=\"false\">\n        <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"></rect><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line><line x1=\"8\" y1=\"3\" x2=\"8\" y2=\"7\"></line><line x1=\"16\" y1=\"3\" x2=\"16\" y2=\"7\"></line></svg>\n        Prenota da solo\n      </button>\n    </div>\n  </header>\n\n  <section class=\"panel\" id=\"chatPanel\">\n    <main id=\"chatMsgs\" aria-live=\"polite\"></main>\n    <form class=\"chatbar\" id=\"chatForm\" autocomplete=\"off\">\n      <input id=\"chatInput\" type=\"text\" maxlength=\"300\" placeholder=\"Scrivi un messaggio…\" enterkeyhint=\"send\">\n      <button class=\"sendbtn\" id=\"chatSend\" type=\"submit\" aria-label=\"Invia\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\"></line><polyline points=\"6 11 12 5 18 11\"></polyline></svg>\n      </button>\n    </form>\n  </section>\n\n  <section class=\"panel\" id=\"bookPanel\" hidden>\n    <div class=\"col\" id=\"bookView\"></div>\n  </section>\n</div>\n\n<script>\n(function(){\n  var DAY_SHORT = ['Lun','Mar','Mer','Gio','Ven','Sab','Dom'];\n  var MONTHS = ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];\n  var MONTHS3 = ['gen','feb','mar','apr','mag','giu','lug','ago','set','ott','nov','dic'];\n  var DAY_LONG = {0:'lunedì',1:'martedì',2:'mercoledì',3:'giovedì',4:'venerdì',5:'sabato',6:'domenica'};\n  var TODAY = new Date();\n  var SLUG = (new URLSearchParams(location.search).get('b') || '').toLowerCase();\n\n  var BUSINESS = { services: [] };\n  var slotsCache = {};\n\n  /* ============== interruttore chat / prenota ============== */\n  var tabChat = document.getElementById('tabChat'), tabBook = document.getElementById('tabBook');\n  var chatPanel = document.getElementById('chatPanel'), bookPanel = document.getElementById('bookPanel');\n  function showTab(which){\n    var chat = which === 'chat';\n    tabChat.setAttribute('aria-pressed', chat ? 'true':'false');\n    tabBook.setAttribute('aria-pressed', chat ? 'false':'true');\n    chatPanel.hidden = !chat; bookPanel.hidden = chat;\n  }\n  tabChat.addEventListener('click', function(){ showTab('chat'); });\n  tabBook.addEventListener('click', function(){ showTab('book'); });\n\n  /* ============== CHAT (vera, collegata a /api/chat) ============== */\n  var CHAT = { sid: null, msgs: [] };\n  (function(){\n    var msgsEl = document.getElementById('chatMsgs');\n    var form = document.getElementById('chatForm');\n    var input = document.getElementById('chatInput');\n    var sendBtn = document.getElementById('chatSend');\n    var busy = false;\n    var KEY = 'lia_chat_' + SLUG;\n\n    function uuid(){\n      if (window.crypto && crypto.randomUUID) return crypto.randomUUID();\n      var hx='0123456789abcdef', s2='';\n      for (var i=0;i<36;i++){ if (i===8||i===13||i===18||i===23) s2+='-'; else s2+=hx.charAt(Math.floor(Math.random()*16)); }\n      return s2;\n    }\n    function loadChat(){\n      try { var raw = localStorage.getItem(KEY); if (raw){ var o=JSON.parse(raw); if (o && o.sid) CHAT = o; } } catch(e){}\n      if (!CHAT.sid) CHAT.sid = uuid();\n    }\n    function saveChat(){ try { CHAT.msgs = CHAT.msgs.slice(-40); localStorage.setItem(KEY, JSON.stringify(CHAT)); } catch(e){} }\n\n    function el(tag, cls){ var e = document.createElement(tag); if (cls) e.className = cls; return e; }\n    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n    function scrollEnd(){ requestAnimationFrame(function(){ requestAnimationFrame(function(){ msgsEl.scrollTo({top:msgsEl.scrollHeight, behavior: reduceMotion?'auto':'smooth'}); }); }); }\n    function calendarUrl(c){ if(!c||!c.start||!c.end)return ''; function esc(x){return String(x||'').replace(/;/g,';').replace(/,/g,',');} function dt(x){return new Date(x).toISOString().replace(/[-:]/g,'').replace(/\\.\\d{3}/,'');} var lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//LIA//Appointment//IT','BEGIN:VEVENT','UID:'+Date.now()+'-'+Math.random().toString(36).slice(2)+'@lia','DTSTAMP:'+dt(new Date().toISOString()),'DTSTART:'+dt(c.start),'DTEND:'+dt(c.end),'SUMMARY:'+esc(c.title||'Appuntamento'),'DESCRIPTION:'+esc(c.description||''),'LOCATION:'+esc(c.location||''),'END:VEVENT','END:VCALENDAR']; return URL.createObjectURL(new Blob([lines.join('\\r\\n')+'\\r\\n'],{type:'text/calendar;charset=utf-8'})); }\n    function googleCalendarUrl(c){ if(!c||!c.start||!c.end)return ''; function dt(x){return new Date(x).toISOString().replace(/[-:]/g,'').replace(/\\.\\d{3}/,'');} return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(c.title||'Appuntamento')+'&dates='+encodeURIComponent(dt(c.start)+'/'+dt(c.end))+'&details='+encodeURIComponent(c.description||'')+'&location='+encodeURIComponent(c.location||''); }\n    function bubble(role, text, isErr, calendar){ var row=el('div','row '+role); var b=el('div','b'+(isErr?' err':'')); b.textContent=text; if(calendar){b.appendChild(document.createElement('br'));var g=el('a','cal-add');g.href=googleCalendarUrl(calendar);g.target='_blank';g.rel='noopener';g.textContent='Google Calendar';b.appendChild(g);} row.appendChild(b); msgsEl.appendChild(row); scrollEnd(); }\n    function addAndSave(role, text, calendar){ CHAT.msgs.push({r:role,t:text,c:calendar||null}); saveChat(); bubble(role, text, false, calendar); }\n    function showTyping(){ var row=el('div','row lia'); row.id='typingRow'; var t=el('div','typing'); t.innerHTML='<i></i><i></i><i></i>'; row.appendChild(t); msgsEl.appendChild(row); scrollEnd(); }\n    function hideTyping(){ var r=document.getElementById('typingRow'); if (r) r.remove(); }\n\n    function startChat(bizName){\n      loadChat();\n      if (!CHAT.msgs.length){\n        showTyping();\n        setTimeout(function(){ hideTyping(); addAndSave('lia', 'Ciao! Sono la segretaria virtuale di ' + bizName + '. Come posso aiutarti?'); }, 500);\n      } else {\n        CHAT.msgs.forEach(function(m){ bubble(m.r, m.t, false, m.c||null); });\n      }\n      input.disabled = false;\n    }\n\n    function send(text){\n      text = (text||'').trim();\n      if (!text || busy) return;\n      busy = true; sendBtn.disabled = true;\n      input.value = '';\n      addAndSave('me', text);\n      showTyping();\n      fetch('/api/chat', {\n        method:'POST', headers:{'Content-Type':'application/json'},\n        body: JSON.stringify({ b: SLUG, s: CHAT.sid, text: text })\n      }).then(function(r){ return r.json().then(function(d){ return {ok:r.ok, data:d}; }); })\n        .then(function(res){\n          hideTyping();\n          if (!res.ok || !res.data.reply){ bubble('lia', 'Scusa, ho avuto un problema. Riprova tra un attimo.', true); }\n          else { addAndSave('lia', res.data.reply, res.data.calendar||null); }\n        }).catch(function(){ hideTyping(); bubble('lia', 'Non riesco a collegarmi. Riprova tra poco.', true); })\n        .then(function(){ busy=false; sendBtn.disabled=false; input.focus(); });\n    }\n    form.addEventListener('submit', function(ev){ ev.preventDefault(); send(input.value); });\n    window.LiaChat = { start: startChat };\n  })();\n\n  /* ============== PRENOTA DA SOLO ============== */\n  var state = { step:0, service:null, viewMonth: new Date(TODAY.getFullYear(), TODAY.getMonth(), 1), date:null, time:null, name:'', phone:'', address:'', errors:{}, submitting:false, submitError:'' };\n\n  function h(tag, attrs){\n    var e = document.createElement(tag); attrs = attrs || {};\n    for (var k in attrs){ var v=attrs[k];\n      if (k==='class') e.className=v; else if (k==='text') e.textContent=v;\n      else if (k.indexOf('on')===0) e.addEventListener(k.slice(2), v);\n      else if (v===true) e.setAttribute(k,''); else if (v!==false && v!=null) e.setAttribute(k,v);\n    }\n    for (var i=2;i<arguments.length;i++){ var c=arguments[i]; if (c==null||c===false) continue;\n      if (Array.isArray(c)) c.forEach(function(x){ if (x) e.appendChild(x.nodeType?x:document.createTextNode(String(x))); });\n      else e.appendChild(c.nodeType?c:document.createTextNode(String(c)));\n    }\n    return e;\n  }\n  function pad(n){ return String(n).padStart(2,'0'); }\n  function dateKey(d){ return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }\n  function sameDay(a,b){ return a && b && dateKey(a)===dateKey(b); }\n  function isPast(d){ var t=new Date(TODAY.getFullYear(),TODAY.getMonth(),TODAY.getDate()); return d < t; }\n  function hmToMin(hm){ var p=hm.split(':'); return +p[0]*60+ +p[1]; }\n  function minToHm(m){ return pad(Math.floor(m/60))+':'+pad(m%60); }\n\n  function fetchSlots(date, service, onDone){\n    var key = service.id + '|' + dateKey(date);\n    if (slotsCache[key]){ onDone(slotsCache[key]); return; }\n    fetch('/api/booking?b=' + encodeURIComponent(SLUG) + '&service=' + encodeURIComponent(service.id) + '&date=' + dateKey(date))\n      .then(function(r){ return r.json().then(function(d){ return {ok:r.ok, data:d}; }); })\n      .then(function(res){ var times = (res.ok && res.data.times) ? res.data.times : []; slotsCache[key] = times; onDone(times); })\n      .catch(function(){ onDone([]); });\n  }\n\n  function nav(label, onNext, canBack, disabled){\n    return h('div',{class:'actions'},\n      h('button',{class:'btn', type:'button', text:label, onclick:onNext, disabled: !!disabled}),\n      canBack ? h('button',{class:'btn text', type:'button', text:'Indietro', onclick:function(){ state.errors={}; goStep(state.step-1); }}) : null\n    );\n  }\n  function field(id,label,input){ return h('div',{class:'field'}, h('label',{for:id,text:label}), input); }\n  function textInput(id,type,val,ph,onInput,extra){\n    var a={id:id,class:'inp',type:type,value:val,placeholder:ph||'',oninput:onInput}; for (var k in (extra||{})) a[k]=extra[k]; return h('input',a);\n  }\n  function iconCal(){ var s=document.createElement('span'); s.innerHTML='<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"></rect><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line><line x1=\"8\" y1=\"3\" x2=\"8\" y2=\"7\"></line><line x1=\"16\" y1=\"3\" x2=\"16\" y2=\"7\"></line></svg>'; return s.firstChild; }\n  function iconCheck(){ var s=document.createElement('span'); s.innerHTML='<svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"4 12 10 18 20 6\"></polyline></svg>'; return s.firstChild; }\n\n  function stepService(){\n    var list = BUSINESS.services.map(function(s){\n      return h('button',{class:'svc-opt', type:'button', 'aria-pressed': state.service&&state.service.id===s.id?'true':'false', onclick:function(){ state.service=s; state.date=null; state.time=null; goStep(1); }},\n        h('span',{class:'mid'}, h('b',{text:s.name}), h('span',{text:s.dur+' min' + (s.atCustomerPlace ? ' \\u00b7 a domicilio' : '')})),\n        h('span',{class:'price', text: (s.price===0||s.price) ? s.price+' €' : ''})\n      );\n    });\n    return h('div', null, h('h2',{id:'h', tabindex:'-1', text:'Cosa vuoi prenotare?'}), h('p',{class:'lead',text:'Scegli il servizio che ti serve.'}), h('div',{class:'svc-list'}, list));\n  }\n\n  function stepDateTime(){\n    state.dtView = state.date ? 'time' : 'cal';\n\n    var monthLabel = h('b', {text: ''});\n    var prevBtn = h('button', {type:'button', 'aria-label':'Mese precedente', onclick:function(){ changeMonth(-1); }}, '\\u2039');\n    var nextBtn = h('button', {type:'button', 'aria-label':'Mese successivo', onclick:function(){ changeMonth(1); }}, '\\u203a');\n    var dowRow = h('div', {class:'cal-dow'}, DAY_SHORT.map(function(d){ return h('span',{text:d}); }));\n    var gridEl = h('div', {class:'cal-grid'});\n    var calPage = h('div', {class:'cal-page'},\n      h('div', {class:'cal-head'}, monthLabel, h('div',{class:'cal-nav'}, prevBtn, nextBtn)),\n      dowRow, gridEl\n    );\n\n    var backBtn = h('button', {class:'time-back', type:'button', onclick: goToCal},\n      h('span', {'aria-hidden':'true'}, '\\u2039'), 'Torna al calendario');\n    var pickedDateEl = h('div', {class:'picked-date'});\n    var timeInner = h('div', {class:'time-inner'});\n    var timePage = h('div', {class:'time-page'}, backBtn, pickedDateEl, timeInner);\n\n    var stage = h('div', {class:'cal-stage'}, calPage, timePage);\n    var calBox = h('div', {class:'cal'}, stage);\n\n    var continueBtn = h('button', {class:'btn', type:'button', text:'Continua', disabled: !(state.date && state.time), onclick:function(){\n      if (state.date && state.time) goStep(2);\n    }});\n    var actions = h('div', {class:'actions'}, continueBtn,\n      h('button',{class:'btn text', type:'button', text:'Indietro', onclick:function(){ state.errors={}; goStep(0); }}));\n\n    function renderMonthGrid(){\n      var mView = state.viewMonth, year = mView.getFullYear(), month = mView.getMonth();\n      var firstDow = (new Date(year, month, 1).getDay() + 6) % 7;\n      var daysInMonth = new Date(year, month+1, 0).getDate();\n      var isCurrentMonth = (year === TODAY.getFullYear() && month === TODAY.getMonth());\n      monthLabel.textContent = MONTHS[month] + ' ' + year;\n      prevBtn.disabled = isCurrentMonth;\n      gridEl.innerHTML = '';\n      for (var i=0;i<firstDow;i++) gridEl.appendChild(h('span',{class:'cal-day pad'}));\n      for (var day=1; day<=daysInMonth; day++){\n        (function(day){\n          var d = new Date(year, month, day);\n          var wd = (d.getDay()+6)%7;\n          var disabled = isPast(d);\n          gridEl.appendChild(h('button', {\n            class: 'cal-day' + (disabled?' off':'') + (sameDay(d, TODAY)?' today':''),\n            type:'button', disabled: disabled,\n            'aria-pressed': sameDay(d, state.date) ? 'true':'false',\n            text: String(day),\n            onclick: function(){ state.date = d; state.time = null; goToTime(); }\n          }));\n        })(day);\n      }\n    }\n\n    function renderTimeContent(){\n      var d = state.date;\n      var myDate = dateKey(d);\n      pickedDateEl.textContent = DAY_LONG[(d.getDay()+6)%7] + ' ' + d.getDate() + ' ' + MONTHS3[d.getMonth()];\n      timeInner.innerHTML = '';\n      timeInner.appendChild(h('div',{class:'time-empty', text:'Cerco gli orari liberi\\u2026'}));\n      setStageHeight();\n      fetchSlots(d, state.service, function(slots){\n        if (dateKey(state.date) !== myDate || state.dtView !== 'time') return; // l'utente ha gia' cambiato giorno\n        timeInner.innerHTML = '';\n        if (!slots.length){ timeInner.appendChild(h('div',{class:'time-empty', text:'Nessun orario libero in questo giorno. Prova un altro giorno.'})); setStageHeight(); return; }\n        var morning = slots.filter(function(t){return t<'13:00';}), afternoon = slots.filter(function(t){return t>='13:00';});\n        function tgrid(list){ return h('div',{class:'time-grid'}, list.map(function(t){\n          return h('button',{class:'time-opt', type:'button', 'aria-pressed': state.time===t?'true':'false', onclick:function(){ pickTime(t); }}, t);\n        })); }\n        if (morning.length) timeInner.appendChild(h('div',{class:'time-group'}, h('h3',{text:'Mattina'}), tgrid(morning)));\n        if (afternoon.length) timeInner.appendChild(h('div',{class:'time-group'}, h('h3',{text:'Pomeriggio'}), tgrid(afternoon)));\n        setStageHeight();\n      });\n    }\n\n    function pickTime(t){\n      state.time = t;\n      timeInner.querySelectorAll('.time-opt').forEach(function(btn){\n        btn.setAttribute('aria-pressed', btn.textContent === t ? 'true' : 'false');\n      });\n      continueBtn.disabled = false;\n      setStageHeight();\n    }\n\n    function setStageHeight(){\n      requestAnimationFrame(function(){\n        var active = state.dtView === 'time' ? timePage : calPage;\n        stage.style.height = active.offsetHeight + 'px';\n      });\n    }\n\n    function goToTime(){\n      state.dtView = 'time';\n      renderTimeContent();\n      stage.classList.add('show-time');\n      setStageHeight();\n    }\n    function goToCal(){\n      state.dtView = 'cal';\n      renderMonthGrid();\n      stage.classList.remove('show-time');\n      setStageHeight();\n    }\n    function changeMonth(delta){\n      state.viewMonth = new Date(state.viewMonth.getFullYear(), state.viewMonth.getMonth()+delta, 1);\n      renderMonthGrid();\n      setStageHeight();\n    }\n\n    renderMonthGrid();\n    if (state.dtView === 'time') renderTimeContent();\n    stage.classList.toggle('show-time', state.dtView === 'time');\n\n    var wrap = h('div', null,\n      h('h2',{id:'h', tabindex:'-1', text:'Quando ti va bene?'}),\n      h('p',{class:'lead'}, state.service.name + ' \\u00b7 ' + state.service.dur + ' min \\u00b7 ' + state.service.price + ' \\u20ac'),\n      calBox, actions\n    );\n    setTimeout(setStageHeight, 0);\n    return wrap;\n  }\n\n  function stepDetails(){\n    var d = state.date;\n    var needsAddress = !!state.service.atCustomerPlace;\n    return h('div', null,\n      h('h2',{id:'h', tabindex:'-1', text:'Ultimo passo.'}),\n      h('p',{class:'lead', text: needsAddress ? 'Ci servono nome, telefono e indirizzo.' : 'Ci servono solo nome e telefono.'}),\n      h('div',{class:'picked'}, h('span',{class:'ic'}, iconCal()),\n        h('div', null, h('b',{text: DAY_LONG[(d.getDay()+6)%7] + ' ' + d.getDate() + ' ' + MONTHS3[d.getMonth()] + ', ' + state.time}), h('span',{text: state.service.name}))),\n      field('name','Nome e cognome', textInput('name','text',state.name,'Es. Nico Bianchi', function(e){ state.name=e.target.value; }, {autocomplete:'name'})),\n      field('phone','Numero di telefono', textInput('phone','tel',state.phone,'Es. 345 123 4567', function(e){ state.phone=e.target.value; }, {autocomplete:'tel', inputmode:'tel'})),\n      needsAddress ? field('address','Indirizzo', textInput('address','text',state.address,'Via, numero civico, città', function(e){ state.address=e.target.value; }, {autocomplete:'street-address'})) : null,\n      state.submitError ? h('div',{class:'err-banner', role:'alert', text: state.submitError}) : null,\n      nav(state.submitting ? 'Un attimo…' : 'Conferma la prenotazione', function(){\n        if (state.name.trim().length<2 || state.phone.replace(/\\D/g,'').length<8) return;\n        if (needsAddress && state.address.trim().length<4) return;\n        submitBooking();\n      }, true, state.submitting)\n    );\n  }\n\n  function submitBooking(){\n    state.submitting = true; state.submitError = ''; goStep(2);\n    fetch('/api/booking?b=' + encodeURIComponent(SLUG), {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({ service: state.service.id, date: dateKey(state.date), time: state.time, name: state.name.trim(), phone: state.phone.trim(), address: state.address.trim() })\n    }).then(function(r){ return r.json().then(function(d){ return {ok:r.ok, status:r.status, data:d}; }); })\n      .then(function(res){\n        state.submitting = false;\n        if (!res.ok){\n          state.submitError = (res.data && res.data.error) ? res.data.error : 'Qualcosa non ha funzionato. Riprova.';\n          if (res.status === 409){ delete slotsCache[state.service.id + '|' + dateKey(state.date)]; state.time = null; }\n          goStep(2);\n          return;\n        }\n        state.calendar = res.data && res.data.calendar ? res.data.calendar : null;\n        goStep(3);\n      })\n      .catch(function(){ state.submitting = false; state.submitError = 'Non riesco a collegarmi. Controlla la connessione e riprova.'; goStep(2); });\n  }\n\n  function googleBookingCalendarUrl(c){ if(!c||!c.start||!c.end)return ''; function dt(x){return new Date(x).toISOString().replace(/[-:]/g,'').replace(/\\.\\d{3}/,'');} return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(c.title||'Appuntamento')+'&dates='+encodeURIComponent(dt(c.start)+'/'+dt(c.end))+'&details='+encodeURIComponent(c.description||'')+'&location='+encodeURIComponent(c.location||''); }\n  function bookingCalendarAction(c){ return c ? h('div',{class:'actions'}, h('a',{class:'btn',href:googleBookingCalendarUrl(c),target:'_blank',rel:'noopener',text:'Google Calendar'})) : null; }\n  function row(a,b){ return h('div',{class:'r'}, h('span',{text:a}), h('b',{text:b})); }\n  function stepDone(){\n    var d = state.date;\n    return h('div',{class:'done'},\n      h('span',{class:'check'}, iconCheck()),\n      h('h2',{id:'h', tabindex:'-1', text:'Prenotazione confermata.'}),\n      h('p',{class:'lead', text:'Barbiere Mario ti aspetta.'}),\n      h('div',{class:'summary'}, row('Servizio', state.service.name), row('Quando', DAY_LONG[(d.getDay()+6)%7] + ' ' + d.getDate() + ' ' + MONTHS3[d.getMonth()] + ' · ' + state.time), h('hr'), row('Prezzo', state.service.price+' €'), h('hr'), row('A nome di', state.name)),\n      bookingCalendarAction(state.calendar), h('div',{class:'actions'}, h('button',{class:'btn text', type:'button', text:'Prenota un altro appuntamento', onclick:function(){\n        state.service=null; state.date=null; state.time=null; state.name=''; state.phone=''; goStep(0);\n      }}))\n    );\n  }\n\n  function goStep(n){ state.step=n; render(); document.getElementById('bookView').scrollTop=0; window.scrollTo(0,0); }\n  function render(){\n    var view = document.getElementById('bookView'); view.innerHTML='';\n    var fns=[stepService, stepDateTime, stepDetails, stepDone];\n    view.appendChild(fns[state.step]());\n  }\n  window.LiaBooking = {\n    setServices: function(list){ BUSINESS.services = list; render(); }\n  };\n})();\n</script>\n<script>\n(function(){\n  var params = new URLSearchParams(location.search);\n  var slug = (params.get('b') || '').toLowerCase();\n\n  function fail(msg){\n    document.querySelector('.top').insertAdjacentHTML('afterend', '');\n    document.body.innerHTML = '';\n    var box = document.createElement('div');\n    box.className = 'err-page';\n    box.textContent = msg;\n    box.style.margin = '60px 20px';\n    document.body.appendChild(box);\n  }\n\n  if (!/^[a-z0-9-]{1,60}$/.test(slug)){ fail('Manca il codice dell\\'attività nel link.'); return; }\n\n  fetch('/api/booking?b=' + encodeURIComponent(slug) + '&info=1')\n    .then(function(r){ return r.json().then(function(d){ return {ok:r.ok, data:d}; }); })\n    .then(function(res){\n      if (!res.ok || !res.data.services){ fail('Questo link non è valido, oppure l\\'attività non ha ancora servizi impostati.'); return; }\n      document.querySelector('.top h1').textContent = res.data.name;\n      document.querySelector('.top small').textContent = (res.data.type || '');\n      document.title = 'Prenota – ' + res.data.name;\n\n      var services = res.data.services.map(function(s){\n        return { id: s.id, name: s.name, dur: s.duration_min, price: s.price_eur, atCustomerPlace: s.at_customer_place };\n      });\n      window.LiaBooking.setServices(services);\n      window.LiaChat.start(res.data.name);\n    })\n    .catch(function(){ fail('Non riesco a collegarmi. Riprova tra poco.'); });\n})();\n</script>\n</body>\n</html>\n";

module.exports = async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Robots-Tag", "noindex");
  const q = req.query || {};
  if (req.method === "GET" && q.asset === "lia-a") {
    res.setHeader("Content-Type", "image/png");
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    return res.status(200).send(Buffer.from("", "base64"));
  }

  try {
    // Messaggio del cliente
    if (req.method === "POST") {
      const body = req.body || {};
      const slug = String(body.b || "");
      const sid = String(body.s || "");
      const text = String(body.text || "").trim().slice(0, 600);
      if (!/^[a-z0-9-]{1,60}$/.test(slug) || !/^[0-9a-f-]{36}$/.test(sid) || !text) {
        return res.status(400).json({ error: "Richiesta non valida" });
      }
      const out = await handleMessage({ channel: "web", contactId: "web:" + sid, phone: null, slug: slug, text: text });
      return res.status(200).json({ reply: out.reply || "", calendar: out.calendar || null });
    }

    // Nome dell'attività (per il titolo della pagina)
    if (q.info === "1") {
      const slug = String(q.b || "");
      if (!/^[a-z0-9-]{1,60}$/.test(slug)) return res.status(404).json({ error: "Link non valido" });
      const biz = await getBusiness(slug);
      if (!biz) return res.status(404).json({ error: "Link non valido" });
      return res.status(200).json({ name: biz.name });
    }

    // La pagina
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    return res.status(200).send(PAGE);
  } catch (e) {
    console.error(e);
    return res.status(500).json({ error: "Errore" });
  }
};
